  "contradictions": [
    "Кандидат утверждает, что совместно производится до 80% европейского кино, тогда как эталон указывает до 70%."
  ],
  "unsupported_claims": [
    "В Европе совместно производится до 80% кино."
  ],
  "supported_by_citations": false,
  "comment": "Кандидат исказил долю: вместо «до 70%» указано «до 80%», что противоречит обязательному факту. Цитата подтверждает 70%, а не 80%, поэтому утверждение ответа не поддержано."
}

